using Microsoft.Dynamics.ApplicationPlatform.XppServices.Instrumentation;

/// <summary>
/// Class for updating processStatus
/// </summary>
class OMGInboundMessageTableChangeStatus extends RunBase
{           
    OMGProcessingStatus     processingStatus;
    DialogField             dialogProcessingStatus;
    Object                  fR;
    List                    list;

    #define.CurrentVersion(1)
    #define.Version1(1)
    #localmacro.CurrentList
    processingStatus
    #endmacro


}

Method.Source:
/// <summary>
///    Returns if the class can run in batch.
/// </summary>
/// <returns>
///    boolean false.
/// </returns>
boolean canGoBatch()
{
    return false;
}

/// <summary>
///    Returns if the class can run in new session.
/// </summary>
/// <returns>
///    boolean false.
/// </returns>
protected boolean canRunInNewSession()
{
    return false;
}

/// <summary>
///    Create dialog.
/// </summary>
/// <returns>
///    returns dialog.
/// </returns>
Object dialog()
{
    DialogRunbase   dialog = super();
    dialog.caption("@SYS24620");
    dialogProcessingStatus = dialog.addFieldValue(enumStr(OMGProcessingStatus), processingStatus);
    return dialog;
}

/// <summary>
/// Update messagestausfield on OMG table
/// </summary>
/// <param name = "_oMGInboundMessageTable">The table to update</param>
void updateStatus(OMGInboundMessageTable _oMGInboundMessageTable)
{
    OMGInboundMessageTable  oMGInboundMessageTable;        
    ;

    select firstonly forupdate oMGInboundMessageTable
        where oMGInboundMessageTable.RecId == _oMGInboundMessageTable.RecId;

    if (!oMGInboundMessageTable)
    {
        error(strFmt("@SYS24642", _oMGInboundMessageTable.RecId));
        return;
    }

    oMGInboundMessageTable.MessageStatus = this.parmProcessingStatus();
    oMGInboundMessageTable.update();
}

/// <summary>
/// Parm method for setting and getting the processStatus
/// </summary>
/// <param name = "_processingStatus">The processStatus to set</param>
/// <returns>The processStatus to get</returns>
private OMGProcessingStatus parmProcessingStatus(OMGProcessingStatus _processingStatus = processingStatus)
{
    processingStatus = _processingStatus;
    return processingStatus;
}

/// <summary>
/// Method for set given processStatus
/// </summary>
/// <returns>The given processStatus </returns>
boolean getFromDialog()
{
    processingStatus = dialogProcessingStatus.value();
    this.parmProcessingStatus(dialogProcessingStatus.value());
    return true;
}

/// <summary>
/// Method to store chosen records i list
/// </summary>
/// <param name = "_oMGInboundMessageTable">The record to ad to list</param>
void insertQueue(OMGInboundMessageTable     _oMGInboundMessageTable)
{
    ;
    list.addEnd(_oMGInboundMessageTable);
}

/// <summary>
/// New-method for setting list
/// </summary>
protected void new()
{
    super();
    list = new List(Types::Record);
}

/// <summary>
/// Method for saving values from Dialog
/// </summary>
/// <returns>Container</returns>
public container pack()
{
    return [#CurrentVersion,#CurrentList];
}

/// <summary>
/// Method for unpacking getLatest-values
/// </summary>
/// <param name = "_packedClass">container to set to set</param>
/// <returns>Returns true/false</returns>
public boolean unpack(container _packedClass)
{
    Integer     version     = conPeek(_packedClass,1);
    container   q;

    switch (version)
    {
        case(#CurrentVersion) :
            [version,#CurrentList,q] = _packedClass;
            break;
        default :
            return false;
    }

    return true;

}

/// <summary>
///    Contains the code that does the actual job of the class.
/// </summary>
// AOSRunMode::client
void run()
{
    #OCCRetryCount
    ListIterator    listI = new ListIterator(list);

    try
    {
        listI.begin();

        while (listI.more())
        {
            ttsbegin;
            this.updateStatus(listI.value());
            ttscommit;

            listI.next();
        }
    }
    catch (Exception::Deadlock)
    {
        retry;
    }
    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::UpdateConflictNotRecovered;
            }
            else
            {
                retry;
            }
        }
        else
        {
            throw Exception::UpdateConflict;
        }
    }

}

/// <summary>
/// Method for validating caller
/// </summary>
/// <param name = "_calledFrom">caller</param>
/// <returns>returns super</returns>
boolean validate(Object _calledFrom = null)
{
    return super();
}

/// <summary>
/// Method for setting records from caller on the class
/// </summary>
/// <param name = "_changeStatus">Class</param>
/// <param name = "_args">args with eg records</param>
static void initFromForm(OMGInboundMessageTableChangeStatus _changeStatus, 
                         Args                               _args)
{
    FormDataSource      fdS;
    Common              common;        
    ;

    if (_args && _args.dataset() && FormDataUtil::getFormDataSource(_args.record()))
    {
        fdS = FormDataUtil::getFormDataSource(_args.record());
        for (common=fdS.getFirst(true) ? fdS.getFirst(true) : _args.record();common;common=fdS.getNext())
        {
            _changeStatus.insertQueue(common);
        }
    }
}

static void main(Args _args)
{
    OMGInboundMessageTableChangeStatus  changeStatus;

    changeStatus = new OMGInboundMessageTableChangeStatus();
    OMGInboundMessageTableChangeStatus::initFromForm(changeStatus,_args);

    if (changeStatus.prompt())
    {
        changeStatus.runOperation();            
    }
}
